using System;using System.Drawing;using System.Drawing.Drawing2D;using System.Windows.Forms;
namespace LoopFive {
 public static partial class Theme {
  public static Color Background=Color.FromArgb(14,17,22),Panel=Color.FromArgb(27,32,40),Line=Color.FromArgb(54,62,75),Text=Color.FromArgb(230,236,245),Muted=Color.FromArgb(145,157,176),Green=Color.FromArgb(31,235,143),Red=Color.FromArgb(255,64,92),Amber=Color.FromArgb(255,185,65),Blue=Color.FromArgb(72,164,255);
  public static Font Small=new Font("Segoe UI",9),Medium=new Font("Segoe UI Semibold",11),Title=new Font("Segoe UI Semibold",23),Ring=new Font("Segoe UI Symbol",27);
  public static void Style(Control c){c.BackColor=Background;c.ForeColor=Text;c.Font=Small;Form form=c as Form;if(form!=null)form.Shown+=delegate{Language.Apply(form);};}
  public static Button Button(string text,Action action){Button b=new DeckButton{Cursor=Cursors.Hand,Text=text,FlatStyle=FlatStyle.Flat,BackColor=Panel,ForeColor=Text,Height=32,Margin=new Padding(4),AutoSize=false};b.FlatAppearance.BorderColor=Line;b.FlatAppearance.MouseOverBackColor=Blend(Panel,Accent,.13f);b.FlatAppearance.MouseDownBackColor=Blend(Panel,Accent,.25f);b.Click+=delegate{try{action();}catch(Exception e){UiMessage.Show(e.Message,"LoopFive",MessageBoxButtons.OK,MessageBoxIcon.Information);}};return b;}
  public static Label Label(string text){return new Label{Text=text,AutoSize=true,ForeColor=Muted,Margin=new Padding(5,8,5,3)};}
  public static ComboBox Combo(string[] items){ComboBox c=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=180,BackColor=Panel,ForeColor=Text,FlatStyle=FlatStyle.Flat};c.DrawMode=DrawMode.OwnerDrawFixed;c.ItemHeight=19;c.DropDownHeight=320;c.DrawItem+=delegate(object sender,DrawItemEventArgs e){if(e.Index<0)return;bool selected=(e.State&DrawItemState.Selected)!=0;using(Brush bg=new SolidBrush(selected?Color.FromArgb(45,65,79):Panel))e.Graphics.FillRectangle(bg,e.Bounds);TextRenderer.DrawText(e.Graphics,Language.T(Convert.ToString(c.Items[e.Index])),Small,e.Bounds,Text,TextFormatFlags.VerticalCenter|TextFormatFlags.Left|TextFormatFlags.EndEllipsis);if((e.State&DrawItemState.Focus)!=0)e.DrawFocusRectangle();};c.Items.AddRange(items);if(items.Length>0)c.SelectedIndex=0;return c;}
  public static NumericUpDown Number(decimal min,decimal max,decimal value){return new NumericUpDown{Minimum=min,Maximum=max,Value=value,Width=80,BackColor=Panel,ForeColor=Text,BorderStyle=BorderStyle.FixedSingle};}
  public static CheckBox Check(string text){return new CheckBox{Text=text,AutoSize=true,Margin=new Padding(7),ForeColor=Text};}
  public static FlowLayoutPanel Flow(){return new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true,Padding=new Padding(10),BackColor=Background};}
  public static Color NamedColor(string s){if(s=="Rosa")return Color.FromArgb(255,135,185);if(s=="Coral")return Color.FromArgb(255,111,102);if(s=="Azul")return Blue;if(s=="Cian")return Color.Cyan;if(s=="Blanco")return Color.White;if(s=="Morado")return Color.FromArgb(191,100,255);if(s=="Ámbar")return Amber;if(s=="Rojo")return Red;return Green;}
 }
 public class Fader:Control {
  float value=.8f;public float Maximum=2;public event Action<float> Changed;bool dragging;
  public float Value{get{return value;}set{this.value=MathX.Clamp(value,0,Maximum);Invalidate();}}
  public Fader(){SetStyle(ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.UserPaint,true);Cursor=Cursors.Hand;Size=new Size(52,150);}
  protected override void OnPaint(PaintEventArgs e){Graphics g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;int center=Width/2;using(Pen p=new Pen(Theme.Line,2))g.DrawLine(p,center,12,center,Height-14);for(int i=0;i<9;i++){int y=12+(Height-26)*i/8;using(Pen p=new Pen(i==4?Theme.Muted:Theme.Line))g.DrawLine(p,center-15,y,center-9,y);}int sy=12+(int)((Height-26)*(1-value/Maximum));using(Brush b=new SolidBrush(Color.FromArgb(4,7,10)))g.FillRectangle(b,center-17,sy-8,34,17);using(Brush b=new LinearGradientBrush(new Rectangle(center-15,sy-7,30,14),Color.FromArgb(92,103,118),Color.FromArgb(35,41,51),90))g.FillRectangle(b,center-15,sy-7,30,14);using(Pen p=new Pen(Theme.Accent,2))g.DrawLine(p,center-13,sy,center+13,sy);}
  void Change(int y){Value=Maximum*(1-(y-12f)/Math.Max(1,Height-26));if(Changed!=null)Changed(Value);}
  protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);Capture=true;dragging=true;Change(e.Y);}
  protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);if(dragging)Change(e.Y);}
  protected override void OnMouseUp(MouseEventArgs e){Capture=false;dragging=false;base.OnMouseUp(e);}
 }
 public class StepEditor:Control {
  public float[] Values=new float[16];public event Action Edited;public int Highlight=-1;bool dragging;
  public StepEditor(){SetStyle(ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.UserPaint,true);Height=130;Cursor=Cursors.Hand;for(int i=0;i<16;i++)Values[i]=.5f;}
  protected override void OnPaint(PaintEventArgs e){Graphics g=e.Graphics;int w=Math.Max(1,Width/16);for(int i=0;i<16;i++){Rectangle r=new Rectangle(i*w+2,5,w-4,Height-25);using(Brush b=new SolidBrush(Theme.Panel))g.FillRectangle(b,r);int h=(int)((Height-27)*Values[i]);using(Brush b=new SolidBrush(i==Highlight?Theme.Amber:Theme.Green))g.FillRectangle(b,i*w+2,Height-22-h,w-4,h);TextRenderer.DrawText(g,(i+1).ToString(),Theme.Small,new Rectangle(i*w,Height-20,w,18),Theme.Muted,TextFormatFlags.HorizontalCenter);}}
  void Edit(int x,int y){int i=Math.Max(0,Math.Min(15,x/Math.Max(1,Width/16)));Values[i]=MathX.Clamp(1-(y-5f)/Math.Max(1,Height-27),0,1);if(Edited!=null)Edited();Invalidate();}
  protected override void OnMouseDown(MouseEventArgs e){dragging=true;Capture=true;Edit(e.X,e.Y);}
  protected override void OnMouseMove(MouseEventArgs e){if(dragging)Edit(e.X,e.Y);}
  protected override void OnMouseUp(MouseEventArgs e){dragging=false;Capture=false;}
 }
 public class TrackStrip:Panel {
  Engine engine;int index;Action<int> edit;Fader fader=new Fader();Button stop,undo,settings,mute,solo,fx,source;Rectangle ring;float[] wave=new float[96];AudioClip lastClip;int waveTick;
  public TrackStrip(Engine e,int i,Action<int> editor){engine=e;index=i;edit=editor;DoubleBuffered=true;SetStyle(ControlStyles.Selectable,true);TabStop=true;BackColor=Theme.Panel;Margin=new Padding(5);Padding=new Padding(10);stop=Theme.Button("■ STOP",delegate{e.Stop(i,false);});undo=Theme.Button("↶",delegate{e.Undo(i,false);});settings=Theme.Button("PISTA / WAV",delegate{edit(i);});mute=Theme.Button("M",delegate{lock(e.Gate){e.Tracks[i].Config.Mute=!e.Tracks[i].Config.Mute;e.Dirty=true;}});solo=Theme.Button("S",delegate{lock(e.Gate){e.Tracks[i].Config.Solo=!e.Tracks[i].Config.Solo;e.Dirty=true;}});fx=Theme.Button("FX",delegate{lock(e.Gate){e.Tracks[i].Config.Effects=!e.Tracks[i].Config.Effects;e.Dirty=true;}});stop.Dispose();settings.Dispose();fx.Dispose();stop=new HardwareOutlineButton{Text="■",Circle=true,Tint=Color.FromArgb(165,195,230)};stop.Click+=delegate{e.Stop(i,false);};settings=new HardwareOutlineButton{Text="TRACK",Tint=Theme.Green};settings.Click+=delegate{edit(i);};fx=new HardwareOutlineButton{Text="FX",Tint=Theme.Red};fx.Click+=delegate{lock(e.Gate){e.Tracks[i].Config.Effects=!e.Tracks[i].Config.Effects;e.Dirty=true;}};Language.Register("FUENTE","SOURCE");source=Theme.Button("FUENTE",SourceMenu);Controls.AddRange(new Control[]{stop,undo,settings,mute,solo,fx,source,fader});fader.Changed+=delegate(float v){lock(engine.Gate){engine.Tracks[index].Config.Level=v;engine.Dirty=true;}};MouseDown+=delegate(object s,MouseEventArgs me){if(ring.Contains(me.Location)){Focus();engine.Action(index);Invalidate();Update();}};Resize+=delegate{Arrange();};}
  void Arrange(){int w=ClientSize.Width,h=ClientSize.Height;fx.SetBounds(18,18,66,27);settings.SetBounds(18,57,66,27);stop.SetBounds(28,98,46,46);source.SetBounds(12,h<500?150:156,85,27);int buttonsY=h<500?181:197;undo.SetBounds(12,buttonsY,31,25);mute.SetBounds(47,buttonsY,27,25);solo.SetBounds(78,buttonsY,27,25);fader.SetBounds(w-80,18,52,Math.Max(80,h-276));int diameter=Math.Min(w-30,170);ring=new Rectangle((w-diameter)/2,h-225,diameter,diameter);}
  void SourceMenu(){ContextMenuStrip menu=new ContextMenuStrip();string[] labels=Language.English?new string[]{"Microphone","Track 1","Track 2","Track 3","Track 4","Track 5","Other tracks mix","Microphone + other tracks"}:new string[]{"Micrófono","Pista 1","Pista 2","Pista 3","Pista 4","Pista 5","Mezcla de otras pistas","Micrófono + otras pistas"};for(int i=0;i<labels.Length;i++){int selected=i;ToolStripMenuItem item=new ToolStripMenuItem(labels[i]);item.Enabled=i!=index+1;item.Checked=RecordingSource.Current(engine.Tracks[index].Config,index)==i;item.Click+=delegate{RecordingSource.Set(engine,index,selected);RefreshState();};menu.Items.Add(item);}menu.Show(source,new Point(0,source.Height));}
  public string DisplayName{get{return Language.TrackName(engine.Tracks[index].Config,index);}}
  public void RefreshState(){Track t=engine.Tracks[index];fader.Value=t.Config.Level;mute.ForeColor=t.Config.Mute?Theme.Red:Theme.Muted;solo.ForeColor=t.Config.Solo?Theme.Amber:Theme.Muted;fx.ForeColor=t.Config.Effects?Theme.Green:Theme.Muted;if(lastClip!=t.Clip||++waveTick%15==0&&t.State==PlayState.Overdubbing){lastClip=t.Clip;Array.Clear(wave,0,wave.Length);if(lastClip!=null)for(int p=0;p<wave.Length;p++){int start=(int)((long)p*lastClip.Length/wave.Length);int end=(int)((long)(p+1)*lastClip.Length/wave.Length);int step=Math.Max(1,(end-start)/32);for(int k=start;k<end;k+=step)wave[p]=Math.Max(wave[p],Math.Abs(lastClip.L[k]));}}Invalidate();}
  protected override void OnPaint(PaintEventArgs e){Graphics g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;g.Clear(Theme.Background);Track t=engine.Tracks[index];PlayState s=t.State;bool recording=s==PlayState.Recording,dubbing=s==PlayState.Overdubbing,pending=s==PlayState.Armed||s==PlayState.WaitingRecord||s==PlayState.WaitingPlay;Color green=Theme.NamedColor(engine.System.PlayColor),red=Theme.NamedColor(engine.System.RecordColor),color=recording?red:dubbing?Theme.NamedColor(engine.System.DubColor):pending?Theme.Blue:green;
   Rectangle card=new Rectangle(1,1,Width-3,Height-3);using(GraphicsPath path=Theme.Round(card,7)){using(Brush b=new LinearGradientBrush(card,Color.FromArgb(25,26,31),Color.FromArgb(8,10,13),0f))g.FillPath(b,path);using(Pen p=new Pen(engine.Config.SelectedTrack==index?Theme.Blend(Theme.Line,Theme.Accent,.5f):Color.FromArgb(62,64,70)))g.DrawPath(p,path);}using(Pen p=new Pen(Color.FromArgb(57,58,64),2))g.DrawLine(p,Width-3,8,Width-3,Height-8);
   int channelX=Width-55;using(Pen p=new Pen(Color.FromArgb(7,8,10),21))g.DrawLine(p,channelX,27,channelX,Math.Max(108,Height-265));using(Pen p=new Pen(Color.FromArgb(75,76,81)))g.DrawLine(p,channelX+18,24,channelX+18,Math.Max(108,Height-265));
   int meterX=Width-100,baseY=Math.Min(fader.Bottom,ring.Top-20);for(int j=0;j<12;j++){using(Brush b=new SolidBrush(t.Peak>j/12f?(j>9?red:green):Color.FromArgb(34,39,42)))g.FillRectangle(b,meterX,baseY-j*4,8,2);}
   if(Height<500){TextRenderer.DrawText(g,(index+1)+"  "+DisplayName,Theme.Small,new Rectangle(12,1,Width-24,17),Color.FromArgb(180,190,205),TextFormatFlags.EndEllipsis);}else{TextRenderer.DrawText(g,(index+1).ToString(),Theme.Title,new Rectangle(14,ring.Top-37,35,33),Color.FromArgb(210,211,220));TextRenderer.DrawText(g,DisplayName,Theme.Small,new Rectangle(49,ring.Top-29,Width-57,20),Color.FromArgb(180,190,205),TextFormatFlags.EndEllipsis);}
   float progress=t.Playing&&t.Clip!=null?(float)(t.Position/t.Clip.Length):recording?(float)((engine.Beat-t.RecordStartBeat)/engine.BarBeats%1):0;float pulse=pending&&Theme.Animate?(float)(.55+.45*Math.Sin((Environment.TickCount&int.MaxValue)*.01)):1;
   using(Brush b=new LinearGradientBrush(ring,Color.FromArgb(58,60,66),Color.FromArgb(6,7,10),70))g.FillEllipse(b,Rectangle.Inflate(ring,4,4));using(Pen p=new Pen(Color.FromArgb(90,92,100),2))g.DrawEllipse(p,Rectangle.Inflate(ring,3,3));
   for(int j=0;j<40;j++){bool lit=recording||dubbing||j<progress*40;using(Pen p=new Pen(lit?Color.FromArgb((int)(255*pulse),red):Color.FromArgb(190,red),8)){p.StartCap=p.EndCap=LineCap.Flat;g.DrawArc(p,ring,-90+j*9,6.3f);}}
   Rectangle middle=Rectangle.Inflate(ring,-13,-13);using(Pen p=new Pen(Color.FromArgb(7,8,11),12))g.DrawEllipse(p,middle);Rectangle inner=Rectangle.Inflate(ring,-24,-24);using(Brush b=new LinearGradientBrush(inner,Color.FromArgb(22,31,32),Color.FromArgb(7,13,15),90))g.FillEllipse(b,inner);using(Pen p=new Pen(Color.FromArgb(70,color),9))g.DrawEllipse(p,inner);using(Pen p=new Pen(color,3))g.DrawEllipse(p,inner);
   int cx=ring.X+ring.Width/2,cy=ring.Y+ring.Height/2;using(Brush b=new SolidBrush(color)){Point[] play={new Point(cx-28,cy-14),new Point(cx-28,cy+14),new Point(cx-5,cy)};if(recording)g.FillEllipse(b,cx-16,cy-16,32,32);else{g.FillPolygon(b,play);g.FillEllipse(b,cx+9,cy-10,20,20);}}using(Pen p=new Pen(color,2))g.DrawLine(p,cx-2,cy+14,cx+9,cy-16);
   string state=recording?"● GRABANDO":dubbing?"● OVERDUB":pending?"ESPERANDO SEÑAL":t.Playing?"▶ REPRODUCIENDO":s==PlayState.Empty?"LISTA PARA GRABAR":"DETENIDA";TextRenderer.DrawText(g,Language.T(state),Theme.Small,new Rectangle(4,Height-43,Width-8,19),color,TextFormatFlags.HorizontalCenter|TextFormatFlags.EndEllipsis);int n=recording?t.RecordL.Count:t.Clip==null?0:t.Clip.Length;TextRenderer.DrawText(g,(n/44100.0).ToString("0.00")+"s   ·   "+RecordingSource.Caption(t.Config,index),Theme.Small,new Rectangle(4,Height-23,Width-8,18),Theme.Muted,TextFormatFlags.HorizontalCenter|TextFormatFlags.EndEllipsis);
   if((recording||dubbing)&&t.AwaitingRecordVisible)engine.AcknowledgeRecordingVisible(index);
  }

 }
}






namespace LoopFive {
 public class RecordingStatusLabel:System.Windows.Forms.Label {
  public Engine Engine;
  protected override void OnPaint(System.Windows.Forms.PaintEventArgs e){base.OnPaint(e);if(Engine==null||Text.IndexOf("GRABANDO",System.StringComparison.Ordinal)<0&&Text.IndexOf("OVERDUB",System.StringComparison.Ordinal)<0)return;for(int i=0;i<5;i++)if(Engine.Tracks[i].AwaitingRecordVisible)Engine.AcknowledgeRecordingVisible(i);}
 }
}
